package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func probeErrorBody(t *testing.T, rec *httptest.ResponseRecorder, wantStatus int, wantCode string) {
	t.Helper()
	if rec.Code != wantStatus {
		t.Fatalf("status = %d, want %d", rec.Code, wantStatus)
	}
	var body struct {
		Error *struct {
			Status  *int   `json:"status"`
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("body is not JSON: %v (body=%q)", err, rec.Body.String())
	}
	if body.Error == nil {
		t.Fatalf("body has no error object: %q", rec.Body.String())
	}
	if body.Error.Status == nil || *body.Error.Status != wantStatus {
		t.Fatalf("error.status = %v, want %d", body.Error.Status, wantStatus)
	}
	if body.Error.Code != wantCode {
		t.Fatalf("error.code = %q, want %q", body.Error.Code, wantCode)
	}
	if body.Error.Message == "" {
		t.Fatalf("error.message is empty")
	}
}

func TestProbeErrorEnvelope(t *testing.T) {
	store := NewStore(time.Minute)
	session := sessionHandler(store)

	rec := httptest.NewRecorder()
	session(rec, httptest.NewRequest(http.MethodPost, "/session", nil))
	probeErrorBody(t, rec, http.StatusBadRequest, "INVALID_ARGUMENT")

	rec = httptest.NewRecorder()
	session(rec, httptest.NewRequest(http.MethodGet, "/session?id=missing", nil))
	probeErrorBody(t, rec, http.StatusNotFound, "SESSION_NOT_FOUND")

	rec = httptest.NewRecorder()
	session(rec, httptest.NewRequest(http.MethodDelete, "/session?id=x", nil))
	probeErrorBody(t, rec, http.StatusMethodNotAllowed, "METHOD_NOT_ALLOWED")
}
EOF
go test -count=1 -run TestProbeErrorEnvelope . ; rc=$? ; rm -f probe_error_envelope_test.go ; exit $rc

